/// <summary>
/// Inserts record into the table.
/// </summary>
public void insert()
{
    this.ConditionQueryPacked = METFulfilmentProfile::defaultQuery().pack();
    super();
}

/// <summary>
/// Returns default fulfilment condition query.
/// </summary>
/// <returns>Query.</returns>
public static Query defaultQuery()
{
    QueryBuildDataSource qbds;
    Query                query;

    query = new Query(queryStr(METFulfilmentConditionQuery));
    qbds  = query.dataSourceTable(tableNum(METReqItemTableInventDimView));

    if (qbds)
    {
        SysQuery::findOrCreateQueryFilter(query, qbds, fieldStr(METReqItemTableInventDimView, InventLocationIdReqMain));
        SysQuery::findOrCreateQueryFilter(query, qbds, fieldStr(METReqItemTableInventDimView, OSCCode));
    }

    qbds = query.dataSourceTable(tableNum(METInventItemOrderSetup));

    if (qbds)
    {
        SysQuery::findOrCreateQueryFilter(query, qbds, fieldStr(METInventItemOrderSetup, FilterCode));
        SysQuery::findOrCreateQueryFilter(query, qbds, fieldStr(METInventItemOrderSetup, ItemType));
    }

    qbds = query.dataSourceTable(tableNum(METSalesLine));

    SysQuery::findOrCreateQueryFilter(query, qbds, fieldStr(METSalesLine, SupplyingWarehouse));

    return query;
}

/// <summary>
/// Finds and return fulfilment strategy profile record.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <param name = "_forUpdate">Optional; false by default.</param>
/// <returns>Fulfilment strategy profile record</returns>
public static METFulfilmentProfile find(METFulfilmentProfileId _profileId, boolean _forUpdate = false)
{
    METFulfilmentProfile profile;

    profile.selectForUpdate(_forUpdate);

    select firstonly profile
        where profile.ProfileId == _profileId;

    return profile;
}
